//   - RV32I instruction subset
//   - Data forwarding for hazard resolution
//   - Branch prediction with flush
//   - 32 x 32-bit register file
//==============================================================================

module riscv_cpu (
    input  wire        clk,
    input  wire        rst_n,

    // Instruction Memory Interface
    output wire [31:0] imem_addr,
    input  wire [31:0] imem_data,

    // Data Memory Interface
    output wire [31:0] dmem_addr,
    output wire [31:0] dmem_wdata,
    output wire        dmem_wen,
    output wire [3:0]  dmem_be,
    input  wire [31:0] dmem_rdata,

    // Debug Interface
    output wire [31:0] debug_pc,
    output wire [31:0] debug_inst
);

    // ------------------------------------------------------------
    // ALU operation encodings
    // ------------------------------------------------------------
    localparam [3:0] ALU_ADD = 4'b0000;
    localparam [3:0] ALU_SUB = 4'b0001;
    localparam [3:0] ALU_AND = 4'b0010;
    localparam [3:0] ALU_OR  = 4'b0011;
    localparam [3:0] ALU_XOR = 4'b0100;
    localparam [3:0] ALU_SLT = 4'b0101;
    localparam [3:0] ALU_SLL = 4'b0110;
    localparam [3:0] ALU_SRL = 4'b0111;
    localparam [3:0] ALU_SRA = 4'b1000;

    // ------------------------------------------------------------
    // Architectural state
    // ------------------------------------------------------------
    reg  [31:0] pc;
    reg  [31:0] regs [0:31];

    integer i;

    // ------------------------------------------------------------
    // IF/ID pipeline register
    // ------------------------------------------------------------
    reg  [31:0] ifid_pc;
    reg  [31:0] ifid_inst;

    // ------------------------------------------------------------
    // ID/EX pipeline register
    // ------------------------------------------------------------
    reg  [31:0] idex_pc;
    reg  [31:0] idex_rs1_data;
    reg  [31:0] idex_rs2_data;
    reg  [4:0]  idex_rs1;
    reg  [4:0]  idex_rs2;
    reg  [4:0]  idex_rd;
    reg  [31:0] idex_imm;
    reg  [2:0]  idex_funct3;
    reg  [3:0]  idex_alu_op;
    reg         idex_regwrite;
    reg         idex_memread;
    reg         idex_memwrite;
    reg         idex_alusrc;
    reg         idex_branch;
    reg         idex_jump;
    reg         idex_jalr;
    reg         idex_link;

    // ------------------------------------------------------------
    // EX/MEM pipeline register
    // ------------------------------------------------------------
    reg  [31:0] exmem_alu_result;
    reg  [31:0] exmem_mem_data;
    reg  [4:0]  exmem_rd;
    reg         exmem_regwrite;
    reg         exmem_memread;
    reg         exmem_memwrite;

    // ------------------------------------------------------------
    // MEM/WB pipeline register
    // ------------------------------------------------------------
    reg  [31:0] memwb_mem_data;
    reg  [31:0] memwb_alu_result;
    reg  [4:0]  memwb_rd;
    reg         memwb_regwrite;
    reg         memwb_memread;

    // ------------------------------------------------------------
    // Hazard / control
    // ------------------------------------------------------------
    reg         stall;
    reg         branch_cond;
    reg         branch_taken;
    reg  [1:0]  fwd_a;
    reg  [1:0]  fwd_b;
    reg  [31:0] alu_result_c;

    wire        jump_taken;
    wire        redirect;
    wire        flush;
    wire [31:0] redirect_pc;
    wire [31:0] pc_next;
    wire [31:0] wb_result;

    // ------------------------------------------------------------
    // ID stage decode wires
    // ------------------------------------------------------------
    wire [6:0]  id_opcode;
    wire [2:0]  id_funct3;
    wire [6:0]  id_funct7;
    wire [4:0]  id_rs1;
    wire [4:0]  id_rs2;
    wire [4:0]  id_rd;

    reg  [31:0] id_imm;
    reg  [31:0] id_rs1_data;
    reg  [31:0] id_rs2_data;
    reg  [3:0]  id_alu_op;
    reg         id_regwrite;
    reg         id_memread;
    reg         id_memwrite;
    reg         id_alusrc;
    reg         id_branch;
    reg         id_jump;
    reg         id_jalr;
    reg         id_link;

    // ------------------------------------------------------------
    // EX stage operand / forwarding
    // ------------------------------------------------------------
    wire [31:0] ex_op_a;
    wire [31:0] ex_op_b;
    wire [31:0] fwd_a_val;
    wire [31:0] fwd_b_val;

    // ============================================================
    // PC
    // ============================================================
    assign imem_addr = pc;

    assign pc_next = redirect ? redirect_pc : (pc + 32'd4);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pc <= 32'd0;                      // D3: fetch from 0x00000000
        else if (redirect)
            pc <= redirect_pc;
        else if (stall)
            pc <= pc;                         // REQ-9: hold PC on stall
        else
            pc <= pc_next;
    end

    // ============================================================
    // IF/ID register
    // ============================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ifid_pc   <= 32'd0;
            ifid_inst <= 32'h00000013;        // NOP
        end else if (flush) begin
            ifid_pc   <= 32'd0;
            ifid_inst <= 32'h00000013;        // REQ-10: kill younger instr
        end else if (stall) begin
            ifid_pc   <= ifid_pc;             // REQ-9: hold
            ifid_inst <= ifid_inst;
        end else begin
            ifid_pc   <= pc;
            ifid_inst <= imem_data;
        end
    end

    // ============================================================
    // ID stage: decode
    // ============================================================
    assign id_opcode = ifid_inst[6:0];
    assign id_funct3 = ifid_inst[14:12];
    assign id_funct7 = ifid_inst[31:25];
    assign id_rs1    = ifid_inst[19:15];
    assign id_rs2    = ifid_inst[24:20];
    assign id_rd     = ifid_inst[11:7];

    // Immediate generation
    always @(*) begin
        case (id_opcode)
            7'b0010011, 7'b0000011, 7'b1100111: begin
                id_imm = {{20{ifid_inst[31]}}, ifid_inst[31:20]};
            end
            7'b0100011: begin
                id_imm = {{20{ifid_inst[31]}}, ifid_inst[31:25], ifid_inst[11:7]};
            end
            7'b1100011: begin
                id_imm = {{19{ifid_inst[31]}}, ifid_inst[31], ifid_inst[7],
                          ifid_inst[30:25], ifid_inst[11:8], 1'b0};
            end
            7'b1101111: begin
                id_imm = {{11{ifid_inst[31]}}, ifid_inst[31], ifid_inst[19:12],
                          ifid_inst[20], ifid_inst[30:21], 1'b0};
            end
            default: begin
                id_imm = 32'd0;
            end
        endcase
    end

    // Register file read (x0 hardwired to 0)
    always @(*) begin
        if (id_rs1 == 5'd0)
            id_rs1_data = 32'd0;
        else
            id_rs1_data = regs[id_rs1];

        if (id_rs2 == 5'd0)
            id_rs2_data = 32'd0;
        else
            id_rs2_data = regs[id_rs2];
    end

    // Control generation
    always @(*) begin
        id_regwrite = 1'b0;
        id_memread  = 1'b0;
        id_memwrite = 1'b0;
        id_alusrc   = 1'b0;
        id_branch   = 1'b0;
        id_jump     = 1'b0;
        id_jalr     = 1'b0;
        id_link     = 1'b0;
        id_alu_op   = ALU_ADD;

        case (id_opcode)
            7'b0110011: begin                     // R-type
                id_regwrite = 1'b1;
                case (id_funct3)
                    3'b000:  id_alu_op = id_funct7[5] ? ALU_SUB : ALU_ADD;
                    3'b111:  id_alu_op = ALU_AND;
                    3'b110:  id_alu_op = ALU_OR;
                    3'b100:  id_alu_op = ALU_XOR;
                    3'b010:  id_alu_op = ALU_SLT;
                    3'b001:  id_alu_op = ALU_SLL;
                    3'b101:  id_alu_op = id_funct7[5] ? ALU_SRA : ALU_SRL;
                    default: id_alu_op = ALU_ADD;
                endcase
            end
            7'b0010011: begin                     // I-type ALU
                id_regwrite = 1'b1;
                id_alusrc   = 1'b1;
                case (id_funct3)
                    3'b000:  id_alu_op = ALU_ADD;
                    3'b111:  id_alu_op = ALU_AND;
                    3'b110:  id_alu_op = ALU_OR;
                    3'b100:  id_alu_op = ALU_XOR;
                    3'b010:  id_alu_op = ALU_SLT;
                    default: id_alu_op = ALU_ADD;
                endcase
            end
            7'b0000011: begin                     // LW
                id_regwrite = 1'b1;
                id_memread  = 1'b1;
                id_alusrc   = 1'b1;
                id_alu_op   = ALU_ADD;
            end
            7'b0100011: begin                     // SW
                id_memwrite = 1'b1;
                id_alusrc   = 1'b1;
                id_alu_op   = ALU_ADD;
            end
            7'b1100011: begin                     // Branch
                id_branch   = 1'b1;
                id_alu_op   = ALU_SUB;
            end
            7'b1101111: begin                     // JAL
                id_regwrite = 1'b1;
                id_jump     = 1'b1;
                id_link     = 1'b1;
                id_alu_op   = ALU_ADD;
            end
            7'b1100111: begin                     // JALR
                id_regwrite = 1'b1;
                id_jump     = 1'b1;
                id_jalr     = 1'b1;
                id_link     = 1'b1;
                id_alusrc   = 1'b1;
                id_alu_op   = ALU_ADD;
            end
            default: begin
                id_regwrite = 1'b0;
            end
        endcase
    end

    // ============================================================
    // ID/EX pipeline register
    // ============================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            idex_pc       <= 32'd0;
            idex_rs1_data <= 32'd0;
            idex_rs2_data <= 32'd0;
            idex_rs1      <= 5'd0;
            idex_rs2      <= 5'd0;
            idex_rd       <= 5'd0;
            idex_imm      <= 32'd0;
            idex_funct3   <= 3'b000;
            idex_alu_op   <= ALU_ADD;
            idex_regwrite <= 1'b0;
            idex_memread  <= 1'b0;
            idex_memwrite <= 1'b0;
            idex_alusrc   <= 1'b0;
            idex_branch   <= 1'b0;
            idex_jump     <= 1'b0;
            idex_jalr     <= 1'b0;
            idex_link     <= 1'b0;
        end else if (flush || stall) begin
            // Insert bubble
            idex_pc       <= 32'd0;
            idex_rs1_data <= 32'd0;
            idex_rs2_data <= 32'd0;
            idex_rs1      <= 5'd0;
            idex_rs2      <= 5'd0;
            idex_rd       <= 5'd0;
            idex_imm      <= 32'd0;
            idex_funct3   <= 3'b000;
            idex_alu_op   <= ALU_ADD;
            idex_regwrite <= 1'b0;
            idex_memread  <= 1'b0;
            idex_memwrite <= 1'b0;
            idex_alusrc   <= 1'b0;
            idex_branch   <= 1'b0;
            idex_jump     <= 1'b0;
            idex_jalr     <= 1'b0;
            idex_link     <= 1'b0;
        end else begin
            idex_pc       <= ifid_pc;
            idex_rs1_data <= id_rs1_data;
            idex_rs2_data <= id_rs2_data;
            idex_rs1      <= id_rs1;
            idex_rs2      <= id_rs2;
            idex_rd       <= id_rd;
            idex_imm      <= id_imm;
            idex_funct3   <= id_funct3;
            idex_alu_op   <= id_alu_op;
            idex_regwrite <= id_regwrite;
            idex_memread  <= id_memread;
            idex_memwrite <= id_memwrite;
            idex_alusrc   <= id_alusrc;
            idex_branch   <= id_branch;
            idex_jump     <= id_jump;
            idex_jalr     <= id_jalr;
            idex_link     <= id_link;
        end
    end

    // ============================================================
    // Hazard detection: load-use stall (REQ-9, D4)
    // ============================================================
    always @(*) begin
        stall = 1'b0;
        if (idex_memread && (idex_rd != 5'd0) &&
            ((idex_rd == ifid_inst[19:15]) || (idex_rd == ifid_inst[24:20])))
            stall = 1'b1;
        else
            stall = 1'b0;
    end

    // ============================================================
    // Forwarding unit (REQ-8, D4)
    // ============================================================
    always @(*) begin
        fwd_a = 2'b00;
        fwd_b = 2'b00;

        if (exmem_regwrite && (exmem_rd != 5'd0) && (exmem_rd == idex_rs1))
            fwd_a = 2'b10;
        else if (memwb_regwrite && (memwb_rd != 5'd0) && (memwb_rd == idex_rs1))
            fwd_a = 2'b01;

        if (exmem_regwrite && (exmem_rd != 5'd0) && (exmem_rd == idex_rs2))
            fwd_b = 2'b10;
        else if (memwb_regwrite && (memwb_rd != 5'd0) && (memwb_rd == idex_rs2))
            fwd_b = 2'b01;
    end

    assign wb_result = memwb_memread ? memwb_mem_data : memwb_alu_result;

    assign fwd_a_val = (fwd_a == 2'b10) ? exmem_alu_result :
                       (fwd_a == 2'b01) ? wb_result        :
                                          idex_rs1_data;

    assign fwd_b_val = (fwd_b == 2'b10) ? exmem_alu_result :
                       (fwd_b == 2'b01) ? wb_result        :
                                          idex_rs2_data;

    // ============================================================
    // EX stage: ALU
    // ============================================================
    assign ex_op_a = idex_link ? idex_pc  : fwd_a_val;
    assign ex_op_b = idex_link ? 32'd4    : (idex_alusrc ? idex_imm : fwd_b_val);

    always @(*) begin
        case (idex_alu_op)
            ALU_ADD: alu_result_c = ex_op_a + ex_op_b;
            ALU_SUB: alu_result_c = ex_op_a - ex_op_b;
            ALU_AND: alu_result_c = ex_op_a & ex_op_b;
            ALU_OR:  alu_result_c = ex_op_a | ex_op_b;
            ALU_XOR: alu_result_c = ex_op_a ^ ex_op_b;
            ALU_SLT: alu_result_c = ($signed(ex_op_a) < $signed(ex_op_b)) ? 32'd1 : 32'd0;
            ALU_SLL: alu_result_c = ex_op_a << ex_op_b[4:0];
            ALU_SRL: alu_result_c = ex_op_a >> ex_op_b[4:0];
            ALU_SRA: alu_result_c = $signed(ex_op_a) >>> ex_op_b[4:0];
            default: alu_result_c = 32'd0;
        endcase
    end

    // ============================================================
    // EX stage: branch / jump resolution (D5)
    // ============================================================
    always @(*) begin
        case (idex_funct3)
            3'b000:  branch_cond = (fwd_a_val == fwd_b_val);
            3'b001:  branch_cond = (fwd_a_val != fwd_b_val);
            3'b100:  branch_cond = ($signed(fwd_a_val) <  $signed(fwd_b_val));
            3'b101:  branch_cond = ($signed(fwd_a_val) >= $signed(fwd_b_val));
            default: branch_cond = 1'b0;
        endcase
    end

    always @(*) begin
        if (idex_branch && branch_cond)
            branch_taken = 1'b1;
        else
            branch_taken = 1'b0;
    end

    assign jump_taken  = idex_jump;
    assign redirect    = branch_taken | jump_taken;
    assign flush       = redirect;

    // D2: JALR target LSB forced to 0
    assign redirect_pc = idex_jalr ? ((fwd_a_val + idex_imm) & 32'hFFFFFFFE)
                                   : (idex_pc + idex_imm);

    // ============================================================
    // EX/MEM pipeline register
    // ============================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            exmem_alu_result <= 32'd0;
            exmem_mem_data   <= 32'd0;
            exmem_rd         <= 5'd0;
            exmem_regwrite   <= 1'b0;
            exmem_memread    <= 1'b0;
            exmem_memwrite   <= 1'b0;
        end else begin
            exmem_alu_result <= alu_result_c;
            exmem_mem_data   <= fwd_b_val;
            exmem_rd         <= idex_rd;
            exmem_regwrite   <= idex_regwrite;
            exmem_memread    <= idex_memread;
            exmem_memwrite   <= idex_memwrite;
        end
    end

    // ============================================================
    // MEM stage: data memory interface
    // ============================================================
    assign dmem_addr  = exmem_alu_result;
    assign dmem_wdata = exmem_mem_data;
    assign dmem_wen   = exmem_memwrite;      // REQ-5: asserted only for SW
    assign dmem_be    = 4'b1111;

    // ============================================================
    // MEM/WB pipeline register
    // ============================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            memwb_mem_data   <= 32'd0;
            memwb_alu_result <= 32'd0;
            memwb_rd         <= 5'd0;
            memwb_regwrite   <= 1'b0;
            memwb_memread    <= 1'b0;
        end else begin
            memwb_mem_data   <= dmem_rdata;
            memwb_alu_result <= exmem_alu_result;
            memwb_rd         <= exmem_rd;
            memwb_regwrite   <= exmem_regwrite;
            memwb_memread    <= exmem_memread;
        end
    end

    // ============================================================
    // WB stage: register file write (x0 ignored, REQ-11)
    // ============================================================
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < 32; i = i + 1)
                regs[i] <= 32'd0;
        end else begin
            if (memwb_regwrite && (memwb_rd != 5'd0))
                regs[memwb_rd] <= wb_result;
            regs[0] <= 32'd0;
        end
    end

    // ============================================================
    // Debug
    // ============================================================
    assign debug_pc   = pc;
    assign debug_inst = imem_data;

endmodule